<template><section class="payment-success"><iframe v-if="content.mode === 'html'" title="Custom payment success screen" sandbox="allow-same-origin" scrolling="no" :srcdoc="html" /><div v-else class="payment-card"><div class="shine"></div><img v-if="content.image || companyLogo" :src="content.image || companyLogo" alt="Store logo" /><p class="status">{{ language === "ms" ? "PEMBAYARAN BERJAYA" : "PAYMENT SUCCESS" }}</p><div class="tick">✓</div><strong><small>{{ currencyLabel }}</small>{{ number(state.grandTotal) }}</strong><p class="title">{{ content.title }}</p><p v-if="content.message" class="message">{{ content.message }}</p><p v-if="content.promo" class="promo">{{ content.promo }}</p><small class="footer">{{ content.footer }}</small></div></section></template>
<script setup lang="ts">import { computed, ref } from "vue"; import type { CustomerDisplayState } from "@/services/customerDisplayChannel"; const props = defineProps<{ state: CustomerDisplayState; language: "en" | "ms" }>(); const companyLogo = ref(localStorage.getItem("xpos.customerDisplay.companyLogo") || ""); const currencyLabel = computed(() => props.state.currency === "MYR" ? "RM" : (props.state.currency || "RM")); const content = computed(() => { const fallback = { mode: "template", title: "Thank You!", message: "Thank you for shopping with Lozira Collection.", footer: "Visit us again ❤️", image: "", promo: "", html: "<h1>Thank You!</h1><p>Thank you for shopping with us.</p>" }; try { return { ...fallback, ...JSON.parse(localStorage.getItem("xpos.customerDisplay.paymentContent") || "{}") }; } catch { return fallback; } }); const html = computed(() => { const doc = new DOMParser().parseFromString(content.value.html || "", "text/html"); doc.querySelectorAll("script,iframe,object,embed,link,style").forEach((node) => node.remove()); doc.querySelectorAll("*").forEach((node) => Array.from(node.attributes).forEach((attribute) => { if (attribute.name.startsWith("on")) node.removeAttribute(attribute.name); })); return `<!doctype html><html><head><meta charset="utf-8"><style>html,body{width:100%;height:100%;margin:0;overflow:hidden}body{display:grid;place-items:center;align-content:center;gap:1rem;padding:3rem;box-sizing:border-box;background:radial-gradient(circle at top,#45305f,#17111f 62%);color:#fff;text-align:center;font:clamp(1rem,2vw,2rem) Inter,system-ui,sans-serif}h1{margin:0;font-size:clamp(2.5rem,7vw,7rem);color:#f4c56c}p{margin:0;max-width:48rem}</style></head><body>${doc.body.innerHTML}</body></html>`; }); function number(value: number) { return new Intl.NumberFormat("en-MY", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(value || 0)); }</script>
<style scoped>.payment-success{height:100%;display:grid;place-items:center;background:#17111f;color:#fff;padding:clamp(1rem,3vw,3rem);box-sizing:border-box}.payment-success iframe{display:block;border:0;width:100%;height:100%;overflow:hidden}.payment-card{position:relative;display:grid;justify-items:center;width:min(100%,62rem);overflow:hidden;border:1px solid rgb(244 197 108/.35);border-radius:2rem;padding:clamp(2rem,5vw,5rem);background:linear-gradient(145deg,#30213f,#181420 65%);box-shadow:0 2rem 5rem rgb(0 0 0/.35);text-align:center}.shine{position:absolute;top:-14rem;left:15%;width:70%;height:22rem;border-radius:50%;background:rgb(244 197 108/.12);filter:blur(2rem)}.payment-card>*:not(.shine){position:relative}.payment-card img{max-width:12rem;max-height:5rem;object-fit:contain;margin-bottom:1.25rem}.status{margin:0;color:#f4c56c;font-size:clamp(.75rem,1.5vw,1.15rem);font-weight:800;letter-spacing:.16em}.tick{display:grid;place-items:center;width:clamp(3.5rem,7vw,6rem);height:clamp(3.5rem,7vw,6rem);margin:1rem 0;border-radius:50%;background:#f4c56c;color:#281b35;font-size:clamp(2rem,4vw,4rem);font-weight:900}.payment-card strong{display:block;color:#fff;font-size:clamp(3rem,9vw,8rem);line-height:1}.payment-card strong small{margin-right:.08em;font-size:.35em;vertical-align:baseline}.title{margin:1.5rem 0 .4rem;font-size:clamp(1.8rem,4vw,4rem);font-weight:800}.message{margin:0;max-width:42rem;font-size:clamp(1rem,1.8vw,1.5rem);opacity:.9}.promo{margin:1.5rem 0 0;padding:.55rem 1rem;border:1px solid #f4c56c;border-radius:999px;max-width:100%;font-weight:700}.footer{margin-top:1.5rem;font-size:clamp(.9rem,1.5vw,1.3rem);opacity:.8}</style>
